import { useCallback, useEffect, useMemo, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import {
  Activity, AlertCircle, ArrowUpRight, Bell, BookOpen, Boxes,
  CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Cloud, Code2,
  Command, Cpu, Database, GitBranch, Globe2, Layers3, Menu, MessageSquare,
  Network, Play, Plus, Radio, RefreshCw, Search, Server, Shield, ShieldCheck,
  Siren, Terminal, Workflow, X, Zap
} from "lucide-react";
import { ExperimentWorkbench, ForensicsConsole, MessagingConsole, ResourceCenter, StreamMonitor } from "./AdvancedPanels";
import { MutualExclusionStudio } from "./MutualExclusionStudio";
import { BeaconProtocolControlRoom } from "./BeaconProtocolControlRoom";
import { GlobalSnapshotDemo } from "./GlobalSnapshotDemo";
import { CommandCenter } from "./CommandCenter";
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import "./command-center.css";
import { VectorClockDemo } from "./VectorClockDemo";
import { LeaderElectionDemo } from "./LeaderElectionDemo";
import { DeploymentStudio } from "./DeploymentStudio";
import { CommunicationDemo } from "./CommunicationDemo";
import { PhysicalClockLab } from "./PhysicalClockLab";
import { LamportClockLab } from "./LamportClockLab";

const API = (import.meta as ImportMeta & {env?: {VITE_API_URL?: string}}).env?.VITE_API_URL || "/api-proxy";
type Incident = {
  id:number; title:string; category:string; severity:"low"|"medium"|"high"|"critical";
  status:"open"|"assigned"|"responding"|"resolved"; location:string; description:string; created_at:string
};
type EventItem = {id:number;event_type:string;source:string;payload:any;created_at:string};
type Overview = {metrics:{active_incidents:number;critical_incidents:number;total_incidents:number;events_recorded:number};services:{name:string;state:string;detail:string;kind:string}[];recent_events:EventItem[]};
type Lab = {concept:string;algorithm?:string;note?:string;[key:string]:any};

const nav = [
  {label:"OPERATIONS",items:[{id:"command",name:"Command centre",icon:Activity},{id:"incidents",name:"Incident response",icon:Siren},{id:"resources",name:"Resources & dispatch",icon:Database},{id:"events",name:"Event ledger",icon:GitBranch},{id:"forensics",name:"Incident forensics",icon:Workflow}]},
  {label:"DISTRIBUTED RUNTIME",items:[{id:"architecture",name:"Service topology",icon:Network},{id:"concepts",name:"Concept laboratory",icon:BookOpen},{id:"lab-messaging",name:"Message-oriented communication",icon:MessageSquare},{id:"lab-stream",name:"Stream-oriented communication",icon:Radio},{id:"lab-physical-clock",name:"Physical clock synchronization",icon:Clock3},{id:"lab-lamport",name:"Lamport logical clocks",icon:GitBranch},{id:"lab-vector",name:"Vector clocks",icon:GitBranch},{id:"lab-snapshot",name:"Global state snapshot",icon:Workflow},{id:"lab-election",name:"Leader election",icon:Network},{id:"lab-mutex",name:"Distributed mutual exclusion",icon:ShieldCheck},{id:"lab-failure",name:"Heartbeat failure detection",icon:Activity}]},
  {label:"INFRASTRUCTURE",items:[{id:"deployment",name:"Docker & Kubernetes",icon:Boxes},{id:"scale",name:"Scaling & resilience",icon:Layers3},{id:"runtime",name:"Runtime diagnostics",icon:Terminal}]}
];

const labList = [
 {id:"physical-clock",title:"Physical clock synchronization",short:"Clock discipline",algorithm:"Berkeley-style coordinator averaging",tag:"TIME",accent:"blue",description:"Estimate node clock offsets and compute bounded corrections toward a coordinator estimate."},
 {id:"lamport",title:"Lamport logical clocks",short:"Event ordering",algorithm:"Happened-before relation",tag:"ORDER",accent:"violet",description:"Use scalar counters to preserve causal order across local, send, and receive events."},
 {id:"snapshot",title:"Global state snapshot",short:"Consistent cut",algorithm:"Chandy–Lamport-style model",tag:"STATE",accent:"cyan",description:"Record process-local states and messages in transit as one consistent global view."},
 {id:"vector",title:"Vector clocks",short:"Causality map",algorithm:"Causality versus concurrency",tag:"CAUSAL",accent:"green",description:"Compare vector timestamps component-wise to distinguish happens-before from concurrency."},
 {id:"election",title:"Leader election",short:"Coordinator recovery",algorithm:"Bully algorithm model",tag:"LEADER",accent:"amber",description:"Model election messages and highest-live-node coordinator selection after failure."},
 {id:"mutex",title:"Distributed mutual exclusion",short:"Safe entry",algorithm:"Ricart–Agrawala model",tag:"LOCK",accent:"rose",description:"Order critical-section requests by logical timestamp and process identifier."},
 {id:"failure",title:"Heartbeat failure detection",short:"Liveness signal",algorithm:"Heartbeat / suspicion threshold",tag:"HEALTH",accent:"orange",description:"Observe missed heartbeats and demonstrate the difference between suspicion and proof."},
 {id:"messaging",title:"Message-oriented communication",short:"Durable events",algorithm:"RabbitMQ durable queue",tag:"BROKER",accent:"blue",description:"Follow an event from HTTP command through PostgreSQL, queue publication, and worker acknowledgement."},
 {id:"stream",title:"Stream-oriented communication",short:"Duplex stream",algorithm:"WebSocket lifecycle",tag:"STREAM",accent:"violet",description:"Inspect upgrade, bidirectional frames, keepalive, and disconnect handling."},
 {id:"infrastructure",title:"Container orchestration",short:"Scale & recover",algorithm:"Docker Compose + Kubernetes",tag:"RUNTIME",accent:"green",description:"Compare desired replicas with observed Pods and run controlled scaling/recovery exercises."}
] as const;

const seedIncidents:Incident[] = [
 {id:104,title:"Medical assistance — Sector 07",category:"Medical",severity:"critical",status:"responding",location:"Sector 07 · Riverside",description:"Multiple callers report a road-side incident. Response team dispatched.",created_at:new Date(Date.now()-1000*60*8).toISOString()},
 {id:103,title:"Power disruption — East grid",category:"Infrastructure",severity:"high",status:"assigned",location:"East grid · Substation 2",description:"Utility coordination needed for a feeder outage.",created_at:new Date(Date.now()-1000*60*26).toISOString()},
 {id:102,title:"Water supply alert — Zone C",category:"Public works",severity:"medium",status:"open",location:"Zone C · Central avenue",description:"Low-pressure alert; awaiting field verification.",created_at:new Date(Date.now()-1000*60*42).toISOString()},
 {id:101,title:"Road obstruction — North access",category:"Transport",severity:"low",status:"resolved",location:"North access · Gate 4",description:"Obstruction cleared by municipal crew.",created_at:new Date(Date.now()-1000*60*90).toISOString()}
];


const demoEvents = [
 {id:9003,event_type:"unit.assignment.updated",source:"dispatch-worker",payload:{unit:"MED-04",zone:"Sector 07"},created_at:new Date(Date.now()-23000).toISOString()},
 {id:9002,event_type:"incident.created",source:"api-gateway",payload:{incident_id:104,severity:"critical"},created_at:new Date(Date.now()-57000).toISOString()},
 {id:9001,event_type:"worker.heartbeat",source:"event-worker",payload:{worker:"worker-01",status:"healthy"},created_at:new Date(Date.now()-98000).toISOString()},
 {id:9000,event_type:"snapshot.completed",source:"concept-lab",payload:{nodes:3,channels:3},created_at:new Date(Date.now()-160000).toISOString()}
];

function cls(...values:(string|false|undefined)[]) {return values.filter(Boolean).join(" ");}
function timeAgo(value:string) {const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return `${seconds}s ago`;if(seconds<3600)return `${Math.floor(seconds/60)}m ago`;return `${Math.floor(seconds/3600)}h ago`;}
function fmtDate(){return new Intl.DateTimeFormat("en-IN",{weekday:"short",day:"2-digit",month:"short",year:"numeric"}).format(new Date());}
async function request<T>(path:string, init?:RequestInit):Promise<T>{const res=await fetch(`${API}${path}`,{headers:{"Content-Type":"application/json",...(init?.headers||{})},...init});if(!res.ok)throw new Error((await res.text()).slice(0,250)||`HTTP ${res.status}`);return res.json();}

function App(){
 const [page,setPage]=useState("command");
 const [overview,setOverview]=useState<Overview|null>(null);
 const [incidents,setIncidents]=useState<Incident[]>(seedIncidents);
 const [events,setEvents]=useState<EventItem[]>(demoEvents);
 const [apiState,setApiState]=useState<"checking"|"connected"|"demo">("checking");
 const [refreshing,setRefreshing]=useState(false);
 const [sidebarOpen,setSidebarOpen]=useState(false);
 const [selectedLab,setSelectedLab]=useState<string>("physical-clock");
 const [labData,setLabData]=useState<Lab>({concept:"Loading concept laboratory"});
 const [labLoading,setLabLoading]=useState(false);
 const [notice,setNotice]=useState("");
 const [search,setSearch]=useState("");
 const [incidentModal,setIncidentModal]=useState(false);
 const [filter,setFilter]=useState("all");
 const [form,setForm]=useState({title:"",category:"Medical",severity:"medium",location:"Control zone",description:""});
 const [expandedEvent,setExpandedEvent]=useState<number|null>(null);
 const [selectedService,setSelectedService]=useState("API gateway");
 const [eventFilter,setEventFilter]=useState("all");

 const loadData=useCallback(async()=>{
  setRefreshing(true);
  try{
   const [o,i,e]=await Promise.all([request<Overview>("/overview"),request<{items:Incident[]}>("/incidents"),request<{items:EventItem[]}>("/events")]);
   setOverview(o);setIncidents(i.items);setEvents(e.items);setApiState("connected");
  }catch{
   setApiState("demo");
   setOverview(prev=>prev||({metrics:{active_incidents:3,critical_incidents:1,total_incidents:4,events_recorded:24},services:[
    {name:"API gateway",state:"demo",detail:"API not reachable · local demonstration data",kind:"runtime"},
    {name:"PostgreSQL",state:"demo",detail:"Runtime state is unavailable",kind:"runtime"},
    {name:"RabbitMQ",state:"demo",detail:"Runtime state is unavailable",kind:"runtime"},
    {name:"Concept labs",state:"up",detail:"Concept explanations and sample traces remain available",kind:"application"}
   ],recent_events:demoEvents}));
  }finally{setRefreshing(false);}
 },[]);

 useEffect(()=>{void loadData();const t=window.setInterval(()=>void loadData(),30000);return()=>window.clearInterval(t);},[loadData]);
 useEffect(()=>{if(page==="labs")void loadLab(selectedLab);},[page,selectedLab]);
 async function loadLab(id:string){setSelectedLab(id);setLabLoading(true);try{setLabData(await request<Lab>(`/labs/${id}`));}catch{setLabData(localLabFallback(id));}finally{setLabLoading(false);}}
 function localLabFallback(id:string):Lab{
  const map:Record<string,Lab>={
   "physical-clock":{concept:"Physical clock synchronization",algorithm:"Berkeley-style averaging",note:"Local illustration — API is offline. Synthetic values only.",coordinator_offset_ms:35,nodes:[{node:"node-1",offset_ms:120,adjustment_ms:-85,corrected_offset_ms:35},{node:"node-2",offset_ms:-35,adjustment_ms:70,corrected_offset_ms:35},{node:"node-3",offset_ms:65,adjustment_ms:-30,corrected_offset_ms:35},{node:"node-4",offset_ms:-10,adjustment_ms:45,corrected_offset_ms:35}],steps:["Coordinator polls node offsets","Offsets are averaged","Relative adjustments are sent","Synthetic nodes converge"]},
   lamport:{concept:"Lamport logical clocks",note:"Local sample trace.",events:[{id:"A1",node:"node-1",event:"create incident",clock:1,relation:"local"},{id:"A2",node:"node-1",event:"publish dispatch request",clock:2,relation:"send"},{id:"B1",node:"node-2",event:"receive request",clock:3,relation:"receive"},{id:"B2",node:"node-2",event:"assign unit",clock:4,relation:"local"},{id:"C1",node:"node-3",event:"refresh inventory",clock:1,relation:"independent"}],rules:["Increment before each event","Send carries current counter","Receive: max(local, received) + 1","Happened-before implies lower Lamport timestamp"]},
   snapshot:{concept:"Global state snapshot",note:"Illustrative state, not a live runtime snapshot.",process_states:[{node:"node-1",state:"recorded",detail:"Initiator state captured"},{node:"node-2",state:"recorded",detail:"Marker received; local state captured"},{node:"node-3",state:"recorded",detail:"Marker received; local state captured"}],channels:[{from:"node-1",to:"node-2",state:"empty",messages:[]},{from:"node-2",to:"node-3",state:"in-transit",messages:["dispatch.updated #104"]},{from:"node-3",to:"node-1",state:"empty",messages:[]}]},
   vector:{concept:"Vector clocks",note:"Synthetic event vectors.",events:[{id:"A",node:"node-1",vector:[1,0,0]},{id:"B",node:"node-1",vector:[2,0,0]},{id:"C",node:"node-2",vector:[1,1,0]},{id:"D",node:"node-3",vector:[0,0,1]}],comparisons:[{a:"A",b:"B",relation:"A happened-before B"},{a:"A",b:"C",relation:"A happened-before C"},{a:"B",b:"C",relation:"concurrent"},{a:"C",b:"D",relation:"concurrent"}]},
   election:{concept:"Leader election",algorithm:"Bully algorithm model",note:"Election is simulated.",leader:5,nodes:[{id:1,state:"alive"},{id:2,state:"alive"},{id:3,state:"alive"},{id:4,state:"failed"},{id:5,state:"leader"}],election:["Node 1 detects missing coordinator","Election messages go to higher IDs","Node 5 wins as highest available node"]},
   mutex:{concept:"Distributed mutual exclusion",algorithm:"Ricart–Agrawala model",note:"No production resource is locked.",requests:[{node:"node-2",timestamp:7,process_id:2},{node:"node-1",timestamp:7,process_id:1},{node:"node-3",timestamp:9,process_id:3}],grant_order:["node-1","node-2","node-3"],steps:["Multicast timestamped REQUEST","Peers order by timestamp and process ID","Higher-priority replies may be deferred","Enter after required replies"]},
   failure:{concept:"Heartbeat failure detection",note:"Synthetic heartbeat timeline; suspicion is not proof.",threshold:3,samples:[{time:"12:00:00",node:"node-1",heartbeat:"received",missed:0},{time:"12:00:01",node:"node-2",heartbeat:"received",missed:0},{time:"12:00:02",node:"node-3",heartbeat:"missed",missed:1},{time:"12:00:03",node:"node-3",heartbeat:"missed",missed:2},{time:"12:00:04",node:"node-3",heartbeat:"suspected",missed:3}],interpretation:"Three consecutive misses cause suspicion."},
   messaging:{concept:"Message-oriented communication",technology:"RabbitMQ",note:"Local illustration. Publish status is only verifiable with the API and broker running.",flow:["API validates command","PostgreSQL event ledger records activity","API publishes durable message to aegisgrid.events","Independent worker records processing acknowledgement"],runtime_configured:false},
   stream:{concept:"Stream-oriented communication",transport:"WebSocket",note:"Lifecycle trace, not a captured live socket session.",lifecycle:["HTTP Upgrade request","101 Switching Protocols","Bidirectional text frames","Ping/Pong keepalive","Close frame"],sample_events:[{type:"incident.created",sequence:101},{type:"unit.assigned",sequence:102},{type:"incident.updated",sequence:103}]},
   infrastructure:{concept:"Container orchestration",note:"Runtime state not available while API is offline. Run these commands against your local runtime.",docker_commands:["docker compose ps","docker compose logs --tail=100 api","docker compose up -d --scale worker=3"],kubernetes_commands:["kubectl get deployments,pods,services -n aegisgrid","kubectl scale deployment/aegisgrid-api --replicas=3 -n aegisgrid","kubectl rollout status deployment/aegisgrid-api -n aegisgrid"]}
  };return map[id]||{concept:"Concept",note:"No local sample available."};
 }

 async function createIncident(e:FormEvent){e.preventDefault();try{const out=await request<{incident:Incident}>("/incidents",{method:"POST",body:JSON.stringify(form)});setIncidents(old=>[out.incident,...old]);setNotice("Incident created and event recorded.");setIncidentModal(false);setForm({title:"",category:"Medical",severity:"medium",location:"Control zone",description:""});void loadData();}catch{const item:Incident={...form,id:Math.max(...incidents.map(i=>i.id),100)+1,status:"open",created_at:new Date().toISOString(),severity:form.severity as Incident["severity"]};setIncidents(old=>[item,...old]);setNotice("API is offline: incident added to this session only. Start Docker Compose to persist it.");setIncidentModal(false);}}
 async function setIncidentStatus(item:Incident,status:Incident["status"]){try{await request(`/incidents/${item.id}`,{method:"PATCH",body:JSON.stringify({status})});void loadData();setNotice(`Incident #${item.id} updated.`);}catch{setIncidents(old=>old.map(i=>i.id===item.id?{...i,status}:i));setNotice("Session-only update: API is offline; status will not persist.");}}
 async function emitEvent(){try{await request("/events/demo",{method:"POST"});setNotice("Demo event emitted. Check the event ledger and worker logs.");void loadData();}catch{setEvents(old=>[{id:Math.max(0,...old.map(e=>e.id))+1,event_type:"dispatch.demo",source:"dashboard-local",payload:{message:"Demo event (session only)"},created_at:new Date().toISOString()},...old]);setNotice("Demo event added to the local view only; broker delivery is unavailable.");}}
 const activeIncidents=incidents.filter(i=>i.status!=="resolved");
 const visibleIncidents=useMemo(()=>incidents.filter(i=>(filter==="all"||i.status===filter||i.severity===filter)&&`${i.title} ${i.location} ${i.category}`.toLowerCase().includes(search.toLowerCase())),[incidents,filter,search]);
 const visibleEvents=events.filter(e=>(eventFilter==="all"||e.event_type.includes(eventFilter))&&`${e.event_type} ${e.source}`.toLowerCase().includes(search.toLowerCase()));
 const services=overview?.services||[];
 const activeLab=labList.find(l=>l.id===selectedLab)||labList[0];
 function navigate(id:string){if(id.startsWith("lab-")){setSelectedLab(id.slice(4));setPage("labs");}else if(id==="experiments"){setPage("command");}else{setPage(id);}setSidebarOpen(false);setNotice("");}
 const headerTitle=nav.flatMap(s=>s.items).find(i=>i.id===page)?.name||"Command centre";

 return <div className="app-shell">
  <aside className={cls("sidebar",sidebarOpen&&"sidebar-open")}>
   <div className="brand"><div className="brand-mark"><Shield size={22}/><span></span></div><div><div className="brand-name">aegis<span>grid</span></div><div className="brand-caption">RESPONSE INTELLIGENCE</div></div><button className="icon-btn mobile-only" onClick={()=>setSidebarOpen(false)} aria-label="Close menu"><X size={18}/></button></div>
   <div className="workspace-switch"><div className="workspace-glyph"><Command size={16}/></div><div className="workspace-copy"><b>Central command</b><span>Emergency operations</span></div><ChevronDown size={15} className="muted-icon"/></div>
   <div className="sidebar-scroll">
    {nav.map(section=><div className="nav-section" key={section.label}><div className="nav-label">{section.label}</div>{section.items.map(item=>{const Icon=item.icon;return <button key={item.id} onClick={()=>navigate(item.id)} className={cls("nav-item",(page===item.id||(page==="labs"&&item.id==="lab-"+selectedLab))&&"active")}><Icon size={17}/><span>{item.name}</span>{item.id==="incidents"&&activeIncidents.length>0&&<span className="nav-counter">{activeIncidents.length}</span>}</button>;})}</div>)}
   </div>
   <div className="sidebar-bottom"><div className="environment-card"><div className="env-top"><span className={cls("status-dot",apiState==="connected"?"green":apiState==="demo"?"amber":"blue")}></span><span>{apiState==="connected"?"Live environment":apiState==="demo"?"Demo environment":"Connecting"}</span><span className="env-chip">DEV</span></div><p>{apiState==="connected"?"API and persistence responding":apiState==="demo"?"API unreachable · sample data active":"Checking service health"}</p><div className="env-line"><span>Gateway</span><b className={cls(apiState==="connected"?"text-green":"text-amber")}>{apiState==="connected"?"Online":"Unverified"}</b></div></div><button className="profile-row" onClick={()=>navigate("docs")}><div className="avatar">AG</div><div className="profile-copy"><b>Operations analyst</b><span>Project workspace</span></div><CircleHelp size={16} className="muted-icon"/></button></div>
  </aside>
  {sidebarOpen&&<button className="sidebar-scrim" onClick={()=>setSidebarOpen(false)} aria-label="Close sidebar"></button>}
  <main className="main-area">
   <header className="topbar"><div className="topbar-left"><button className="icon-btn mobile-only" onClick={()=>setSidebarOpen(true)} aria-label="Open menu"><Menu size={20}/></button><div className="breadcrumbs"><span>AEGISGRID</span><ChevronRight size={14}/><b>{headerTitle.toUpperCase()}</b></div></div><div className="topbar-actions"><div className="date-display"><Clock3 size={14}/>{fmtDate()}</div><button className="icon-btn search-shortcut" onClick={()=>document.getElementById("global-search")?.focus()} aria-label="Search"><Search size={17}/></button><button className="icon-btn notification-btn" onClick={()=>setNotice("You’re all caught up. Notifications are local to this demonstration.")} aria-label="Notifications"><Bell size={17}/><i></i></button><div className="topbar-divider"></div><div className="avatar avatar-small">AG</div></div></header>
   <div className="page-content">
    {notice&&<div className="notice"><CheckCircle2 size={16}/><span>{notice}</span><button onClick={()=>setNotice("")} aria-label="Dismiss"><X size={15}/></button></div>}
    {page==="command"&&<CommandCenter overview={overview} incidents={incidents} events={events} services={services} apiState={apiState} refreshing={refreshing} onRefresh={loadData} onCreate={()=>setIncidentModal(true)} onEmit={emitEvent} onNavigate={navigate} />}
    {page==="resources"&&<ResourceCenter/>}
    {page==="concepts"&&<ConceptsPage onNavigate={navigate}/>}
    {page==="delivery"&&<ProjectDeliveryPage onNavigate={navigate}/>}
    {page==="messaging"&&<MessagingConsole/>}
    {page==="stream"&&<StreamMonitor/>}
    {page==="experiments"&&<ExperimentWorkbench/>}
    {page==="labs"&&selectedLab==="snapshot"&&<GlobalSnapshotDemo onBack={()=>navigate("lab-physical-clock")}/>}
    {page==="labs"&&selectedLab==="mutex"&&<MutualExclusionStudio/>}
    {page==="labs"&&selectedLab==="failure"&&<BeaconProtocolControlRoom/>}
    {page==="snapshot"&&<GlobalSnapshotDemo onBack={()=>navigate("experiments")}/>}
    {page==="vector-demo"&&<VectorClockDemo onBack={()=>navigate("experiments")}/>}
    {page==="election-demo"&&<LeaderElectionDemo onBack={()=>navigate("experiments")}/>}
    {page==="labs"&&selectedLab==="election"&&<LeaderElectionDemo onBack={()=>navigate("experiments")}/>}
    {page==="labs"&&selectedLab==="vector"&&<VectorClockDemo onBack={()=>navigate("experiments")}/>}
    {page==="incidents"&&<IncidentsPage incidents={visibleIncidents} filter={filter} setFilter={setFilter} search={search} setSearch={setSearch} onCreate={()=>setIncidentModal(true)} onUpdate={setIncidentStatus}/>}
    {page==="forensics"&&<ForensicsConsole/>}
    {page==="events"&&<EventsPage events={visibleEvents} eventFilter={eventFilter} setEventFilter={setEventFilter} search={search} setSearch={setSearch} expanded={expandedEvent} setExpanded={setExpandedEvent} onEmit={emitEvent}/>}
    {page==="labs"&&selectedLab==="messaging"&&<CommunicationDemo initialMode="messaging" onBack={()=>navigate("experiments")}/>}
    {page==="labs"&&selectedLab==="stream"&&<CommunicationDemo initialMode="stream" onBack={()=>navigate("experiments")}/>}
    {page==="labs"&&selectedLab!=="messaging"&&selectedLab!=="stream"&&selectedLab!=="snapshot"&&selectedLab!=="vector"&&selectedLab!=="election"&&selectedLab!=="mutex"&&selectedLab!=="failure"&&<LabsPage selectedLab={selectedLab} activeLab={activeLab} labData={labData} loading={labLoading} onSelect={loadLab} onEmit={emitEvent}/>}
    {page==="architecture"&&<ArchitecturePage services={services} apiState={apiState} onSelect={(name)=>{setSelectedService(name);navigate("runtime");}}/>}
    {page==="scale"&&<ScalePage apiState={apiState} onNavigate={navigate}/>}
    {page==="deployment"&&<DeploymentStudio onBack={()=>navigate("command")}/>}
    {page==="runtime"&&<RuntimePage services={services} apiState={apiState} selectedService={selectedService} onSelect={setSelectedService} onRefresh={loadData}/>}
    {page==="docs"&&<DocsPage onNavigate={navigate}/>}
    <footer className="footer"><span>AEGISGRID <i>·</i> DISTRIBUTED RESPONSE PLATFORM</span><span>Academic systems lab <b>•</b> v1.0.0</span></footer>
   </div>
  </main>
  {incidentModal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setIncidentModal(false);}}><form className="modal-panel" onSubmit={createIncident}><div className="modal-head"><div><div className="eyebrow">RESPONSE INTAKE</div><h2>Create incident</h2><p>Record a new event for coordination and traceability.</p></div><button type="button" className="icon-btn" onClick={()=>setIncidentModal(false)} aria-label="Close"><X size={19}/></button></div><label>Incident title<input required minLength={3} maxLength={180} placeholder="e.g. Medical assistance required" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><div className="form-grid"><label>Category<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option>Medical</option><option>Infrastructure</option><option>Public works</option><option>Transport</option><option>Security</option><option>Other</option></select></label><label>Severity<select value={form.severity} onChange={e=>setForm({...form,severity:e.target.value})}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="critical">Critical</option></select></label></div><label>Location<input required placeholder="Zone, sector or landmark" value={form.location} onChange={e=>setForm({...form,location:e.target.value})}/></label><label>Description<textarea rows={3} placeholder="Brief context for response teams…" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><div className="modal-foot"><span><ShieldCheck size={15}/> Auditable event trail</span><button type="button" className="btn-secondary" onClick={()=>setIncidentModal(false)}>Cancel</button><button className="btn-primary" type="submit"><Plus size={16}/> Create incident</button></div></form></div>}
 </div>;
}

function PageIntro({eyebrow,title,subtitle,actions}:{eyebrow:string;title:string;subtitle:string;actions?:ReactNode}){
 return <div className="page-intro"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{actions&&<div className="intro-actions">{actions}</div>}</div>;
}
function MetricCard({label,value,detail,icon:Icon,tone,trend}:{label:string;value:string|number;detail:string;icon:any;tone:string;trend?:string}){
 return <div className="metric-card"><div className="metric-top"><span>{label}</span><div className={cls("metric-icon",tone)}><Icon size={18}/></div></div><div className="metric-value">{value}</div><div className="metric-foot"><span>{detail}</span>{trend&&<span className="metric-trend"><ArrowUpRight size={13}/>{trend}</span>}</div></div>;
}
function SectionHead({title,meta,action}:{title:string;meta?:string;action?:React.ReactNode}){return <div className="section-head"><div><h3>{title}</h3>{meta&&<span>{meta}</span>}</div>{action}</div>;}
function StatusPill({status}:{status:string}){return <span className={cls("status-pill",status.toLowerCase().replace(" ","-"))}><i></i>{status.replace("-"," ")}</span>;}
function SeverityBadge({severity}:{severity:string}){return <span className={cls("severity",severity)}><i></i>{severity}</span>;}

function SearchControl({value,onChange,placeholder="Search incidents, events…"}:{value:string;onChange:(v:string)=>void;placeholder?:string}){
 return <label className="search-control"><Search size={16}/><input id="global-search" value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>{value&&<button type="button" onClick={()=>onChange("")} aria-label="Clear search"><X size={14}/></button>}<kbd>⌘ K</kbd></label>;
}
function IncidentsPage({incidents,filter,setFilter,search,setSearch,onCreate,onUpdate}:{incidents:Incident[];filter:string;setFilter:(s:string)=>void;search:string;setSearch:(s:string)=>void;onCreate:()=>void;onUpdate:(i:Incident,s:Incident["status"])=>void}){
 return <><PageIntro eyebrow="RESPONSE / CASE MANAGEMENT" title="Incident response" subtitle="Track incoming cases, prioritize response, and keep status transitions auditable." actions={<button className="btn-primary" onClick={onCreate}><Plus size={16}/> Create incident</button>}/><div className="metric-grid compact-metrics"><MetricCard label="All visible" value={incidents.length} detail="Current filter" icon={Layers3} tone="tone-blue"/><MetricCard label="Critical" value={incidents.filter(i=>i.severity==="critical").length} detail="Highest urgency" icon={AlertCircle} tone="tone-red"/><MetricCard label="Responding" value={incidents.filter(i=>i.status==="responding").length} detail="Unit en route" icon={Radio} tone="tone-green"/><MetricCard label="Resolved" value={incidents.filter(i=>i.status==="resolved").length} detail="Closed cases" icon={CheckCircle2} tone="tone-purple"/></div><section className="panel full-panel"><div className="table-toolbar"><div className="filter-tabs">{["all","open","assigned","responding","resolved","critical"].map(f=><button key={f} onClick={()=>setFilter(f)} className={filter===f?"selected":""}>{f==="all"?"All incidents":f[0].toUpperCase()+f.slice(1)}</button>)}</div><SearchControl value={search} onChange={setSearch}/></div><div className="table-wrap"><table className="data-table"><thead><tr><th>INCIDENT / LOCATION</th><th>CATEGORY</th><th>SEVERITY</th><th>STATUS</th><th>CREATED</th><th>NEXT ACTION</th></tr></thead><tbody>{incidents.map(i=><tr key={i.id}><td><div className="incident-title"><span className="incident-id">#{i.id}</span><div><b>{i.title}</b><span>{i.location}</span></div></div></td><td><span className="category-label">{i.category}</span></td><td><SeverityBadge severity={i.severity}/></td><td><StatusPill status={i.status}/></td><td className="time-cell">{timeAgo(i.created_at)}</td><td><select className="inline-select" value={i.status} onChange={e=>onUpdate(i,e.target.value as Incident["status"])} aria-label={`Change status for ${i.title}`}><option value="open">Set open</option><option value="assigned">Assign</option><option value="responding">Responding</option><option value="resolved">Resolve</option></select></td></tr>)}</tbody></table>{incidents.length===0&&<div className="empty-state"><Search size={24}/><b>No matching incidents</b><span>Try another status filter or search query.</span></div>}</div><div className="panel-foot"><span>{incidents.length} record(s) match this view</span><span>Source: {incidents.some(i=>i.id>1000)?"session demonstration":"incident API / session data"}</span></div></section><div className="info-strip"><ShieldCheck size={17}/><div><b>Audit behavior</b><span>Incident creation and status transitions write event records. When the API is offline, the UI explicitly marks edits as session-only instead of claiming persistence.</span></div></div></>;
}

function EventsPage({events,eventFilter,setEventFilter,search,setSearch,expanded,setExpanded,onEmit}:{events:EventItem[];eventFilter:string;setEventFilter:(s:string)=>void;search:string;setSearch:(s:string)=>void;expanded:number|null;setExpanded:(n:number|null)=>void;onEmit:()=>void}){
 const typeCounts=events.reduce<Record<string,number>>((acc,e)=>{const prefix=e.event_type.split(".")[0];acc[prefix]=(acc[prefix]||0)+1;return acc;},{});
 return <><PageIntro eyebrow="OBSERVABILITY / EVENT FORENSICS" title="Event ledger" subtitle="Inspect event order, source services, payload details, and the path between request and worker." actions={<button className="btn-primary" onClick={onEmit}><Zap size={15}/> Emit test event</button>}/><div className="metric-grid compact-metrics"><MetricCard label="Visible events" value={events.length} detail="Current results" icon={GitBranch} tone="tone-blue"/><MetricCard label="Incident events" value={typeCounts.incident||0} detail="Lifecycle changes" icon={Siren} tone="tone-orange"/><MetricCard label="Worker events" value={typeCounts.worker||0} detail="Consumer activity" icon={Cpu} tone="tone-green"/><MetricCard label="Other domains" value={Object.keys(typeCounts).length} detail="Event type families" icon={Layers3} tone="tone-purple"/></div><section className="panel full-panel"><div className="table-toolbar event-toolbar"><div className="filter-tabs">{[{v:"all",l:"All events"},{v:"incident",l:"Incidents"},{v:"worker",l:"Worker"},{v:"dispatch",l:"Dispatch"},{v:"snapshot",l:"Snapshot"}].map(f=><button key={f.v} className={eventFilter===f.v?"selected":""} onClick={()=>setEventFilter(f.v)}>{f.l}</button>)}</div><SearchControl value={search} onChange={setSearch} placeholder="Search event type or source…"/></div><div className="ledger-list">{events.map(e=><div className="ledger-item" key={e.id}><button className="ledger-main" onClick={()=>setExpanded(expanded===e.id?null:e.id)}><div className="ledger-symbol"><GitBranch size={16}/></div><div className="ledger-primary"><b>{e.event_type}</b><span>{e.source} <i>·</i> {new Date(e.created_at).toLocaleString()}</span></div><code>EVT-{String(e.id).padStart(5,"0")}</code><ChevronDown size={16} className={cls("expand-chevron",expanded===e.id&&"rotated")}/></button>{expanded===e.id&&<div className="event-detail"><div className="detail-heading"><span>EVENT PAYLOAD</span><span>JSON / READ ONLY</span></div><pre>{JSON.stringify(e.payload,null,2)}</pre><div className="detail-meta"><span><Clock3 size={13}/> {e.created_at}</span><span><Database size={13}/> {typeof e.id==="number"&&e.id<1000?"API event ledger or demonstration data":"Local example record"}</span></div></div>}</div>)}{events.length===0&&<div className="empty-state">No event records match these filters.</div>}</div><div className="panel-foot"><span>Events are shown newest first</span><span>Expand a row to inspect payload JSON</span></div></section><div className="info-strip"><AlertCircle size={17}/><div><b>Delivery semantics</b><span>The API reports RabbitMQ publication outcome per event. A committed database record is not the same as confirmed broker delivery or worker processing; consult the broker status and worker logs.</span></div></div></>;
}

function LabsPage({selectedLab,activeLab,labData,loading,onSelect,onEmit}:{selectedLab:string;activeLab:typeof labList[number];labData:Lab|null;loading:boolean;onSelect:(s:string)=>void;onEmit:()=>void}){
 const [showTheory,setShowTheory]=useState(true);
 if(selectedLab==="physical-clock") return <PhysicalClockLab onBack={()=>onSelect("snapshot")}/>;
 if(selectedLab==="lamport") return <LamportClockLab onBack={()=>onSelect("snapshot")}/>;
 const data:Lab=labData||{concept:"Loading concept laboratory"};
 return <><PageIntro eyebrow="ACADEMIC LABS / DISTRIBUTED COMPUTING" title="Concept laboratory" subtitle="Inspectable experiments for time, causality, coordination, fault detection, and communication." actions={<span className="simulation-flag"><span className="status-dot blue"></span> Teaching models</span>}/><div className="lab-overview-strip"><div><div className="mini-label">MODEL LIBRARY</div><b>10 concept modules</b><span>8 algorithm labs · communication · runtime</span></div><div><div className="mini-label">EXECUTION MODE</div><b>Inspectable traces</b><span>Each lab labels simulation vs runtime observation</span></div><div><div className="mini-label">LEARNING PATH</div><b>Time → Causality → Coordination</b><span>Then transport, scaling and recovery</span></div></div><div className="labs-layout"><aside className="lab-catalog"><div className="catalog-head"><div className="eyebrow">MODULES</div><span>{labList.length} LABS</span></div>{labList.map((lab,index)=><button key={lab.id} className={cls("lab-choice",selectedLab===lab.id&&"selected")} onClick={()=>onSelect(lab.id)}><div className={cls("lab-number",`lab-${lab.accent}`)}>{String(index+1).padStart(2,"0")}</div><div className="lab-choice-copy"><b>{lab.title}</b><span>{lab.algorithm}</span></div><ChevronRight size={15}/></button>)}<div className="catalog-note"><BookOpen size={16}/><p>Each model is deliberately small enough to inspect step-by-step. Trace data is synthetic unless an explicit runtime check is described.</p></div></aside><div className="lab-workspace"><section className="lab-hero panel"><div className="lab-hero-top"><span className={cls("lab-tag",`tag-${activeLab.accent}`)}>{activeLab.tag}</span><span className="simulation-label"><span className="status-dot" style={{background:activeLab.id==="messaging"||activeLab.id==="infrastructure"?"#42c9a5":"#7893ff"}}></span>{activeLab.id==="messaging"?"Runtime-backed when connected":activeLab.id==="infrastructure"?"Runtime inspection guide":"Educational simulation"}</span></div><div className="eyebrow">DISTRIBUTED SYSTEMS / LAB {String(labList.findIndex(l=>l.id===selectedLab)+1).padStart(2,"0")}</div><h2>{data.concept||activeLab.title}</h2><p>{activeLab.description}</p><div className="lab-hero-meta"><div><span>ALGORITHM / MODEL</span><b>{data.algorithm||activeLab.algorithm}</b></div><div><span>OUTPUT TYPE</span><b>{activeLab.id==="messaging"?"Broker delivery / message flow":activeLab.id==="infrastructure"?"Runtime commands & observed state":"Structured event trace"}</b></div><button className="btn-secondary" onClick={()=>setShowTheory(v=>!v)}><BookOpen size={15}/>{showTheory?"Hide concept notes":"Show concept notes"}</button></div></section>
  {showTheory&&<section className="panel theory-panel"><SectionHead title="Concept briefing" meta="Core mechanism and what to observe"/><p>{data.note||"This is a deterministic educational model intended to make protocol behavior visible. It does not alter or impersonate a live distributed runtime."}</p><div className="theory-grid"><div><span className="theory-index">01</span><b>Mechanism</b><p>{conceptMechanism(selectedLab)}</p></div><div><span className="theory-index">02</span><b>Observe</b><p>{conceptObserve(selectedLab)}</p></div><div><span className="theory-index">03</span><b>Limitations</b><p>{conceptLimit(selectedLab)}</p></div></div></section>}
  <section className="panel result-panel"><SectionHead title="Experiment output" meta={loading?"Retrieving model trace…":"Structured model response"} action={<button className="text-link" onClick={()=>onSelect(selectedLab)}><RefreshCw size={13}/> Re-run model</button>}/>{loading?<div className="loading-state"><RefreshCw size={20} className="spin"/> Loading model output…</div>:<LabOutput id={selectedLab} data={data}/>}<div className="lab-result-foot"><span><span className="status-dot green"></span> Model response ready</span><span>JSON-backed interactive view</span></div></section>
  <section className="panel lab-steps-panel"><SectionHead title="How to demonstrate this concept" meta="Suggested lab walkthrough"/><div className="walkthrough-steps">{conceptSteps(selectedLab).map((step,i)=><div className="walk-step" key={step}><span>{String(i+1).padStart(2,"0")}</span><p>{step}</p></div>)}</div>{selectedLab==="messaging"&&<button className="btn-primary" onClick={onEmit}><Zap size={15}/> Publish demonstration event</button>}</section>
 </div></div></>;
}

function conceptMechanism(id:string){const m:Record<string,string>={"physical-clock":"A coordinator estimates clock offsets, averages the observations, and sends relative corrections to nodes.","lamport":"Scalar logical counters advance on events and merge received timestamps using max(local, remote) + 1.","snapshot":"A marker protocol captures process state and tracks in-transit messages to form one global cut.","vector":"Each process maintains one counter per process; component-wise comparison can identify causality and concurrency.","election":"Nodes communicate election messages; in the Bully model the highest available identifier becomes coordinator.","mutex":"Requests are ordered by logical timestamp and process ID; permission replies gate critical-section entry.","failure":"Heartbeats indicate recent liveness. A threshold of missed signals marks a node suspected, not definitively failed.","messaging":"An API event is committed to the ledger and published to a durable RabbitMQ queue; a separate worker consumes it.","stream":"A WebSocket upgrades an HTTP connection to a long-lived bidirectional stream with frames and keepalive.","infrastructure":"Container images package processes; Compose wires services for local work and Kubernetes manages desired replicas and recovery."};return m[id]||"Inspect the trace to understand the protocol.";}
function conceptObserve(id:string){const m:Record<string,string>={"physical-clock":"Compare each synthetic offset with the coordinator estimate and signed adjustment needed to converge.","lamport":"Follow local counters and the send/receive edges. Independent events can be ordered numerically without being causally related.","snapshot":"Compare local process states with each channel state; an in-transit message belongs in the channel portion of the cut.","vector":"Contrast A→B with B∥C. Incomparable vectors indicate concurrent events in this model.","election":"Remove a coordinator in the model and observe election traffic to higher-ID nodes before a winner is selected.","mutex":"Two requests with equal timestamps are broken by process ID, which produces a deterministic priority order.","failure":"Watch missed count advance to the suspicion threshold and discuss false positives caused by packet loss or long pauses.","messaging":"Check API response broker field, RabbitMQ queue/management view and worker logs; compare DB commit with consumer acknowledgement.","stream":"Follow Upgrade, 101 response, bidirectional frames, ping/pong and clean close behavior.","infrastructure":"Scale a deployment, observe ready replicas, delete a test Pod and confirm a controller creates a replacement."};return m[id]||"Inspect result details.";}
function conceptLimit(id:string){const m:Record<string,string>={"physical-clock":"Synthetic offsets do not measure your machine’s clocks or model network delay uncertainty.","lamport":"Lamport clocks preserve the happened-before implication, but L(a) < L(b) alone does not prove causality.","snapshot":"This teaching trace is not a distributed snapshot taken from running processes.","vector":"The vectors are fixed examples; production vector-clock metadata can grow with participants.","election":"No services are killed and no runtime leader changes as a side effect of this simulation.","mutex":"The demonstration does not lock a shared database row or provide a production coordination primitive.","failure":"Timeout-based detectors cannot perfectly distinguish a crashed process from a slow or partitioned process.","messaging":"Publish success alone does not prove a worker processed a message; inspect consumer ledger and acknowledgement behavior.","stream":"The trace is illustrative; only the API WebSocket endpoint is a live socket when the stack is running.","infrastructure":"Use metrics and kubectl/docker outputs from your own runtime; a dashboard sample is not proof of cluster state."};return m[id]||"Keep simulation and runtime evidence distinct.";}
function conceptSteps(id:string){const m:Record<string,string[]>={"physical-clock":["Read the node offsets in milliseconds.","Calculate the coordinator’s average offset.","Inspect the sign of each adjustment (target − current).","Explain real systems’ delay and clock-drift limitations."],"lamport":["Identify each process’s local event sequence.","Find a message send and corresponding receive.","Verify the receive counter is max(local, sent) + 1.","Compare independent events and discuss the limits of scalar clocks."],"snapshot":["Start with the initiator’s local state.","Follow marker propagation to each process.","Inspect the channel that contains an in-transit message.","Explain why a consistent cut must not lose causal messages."],"vector":["Read each event’s vector components in node order.","Compare two vectors component-by-component.","Identify a happened-before pair.","Identify incomparable concurrent vectors."],"election":["Mark which node is unavailable in the sample.","Inspect election-message escalation.","Select the highest live node ID.","Explain split-brain and membership assumptions outside this simple model."],"mutex":["Read the timestamped requests.","Apply lexicographic order (timestamp, process ID).","Inspect the resulting grant order.","Discuss deferred replies and deadlock assumptions."],"failure":["Read heartbeat samples sequentially.","Count consecutive misses for the target node.","Observe when the suspicion threshold is reached.","Discuss false positives and adaptive timeouts."],"messaging":["Create an incident or emit the demo event.","Inspect its persisted event record and broker result.","Inspect the durable queue and consumer logs.","Verify a worker processing record rather than inferring from publication alone."],"stream":["Connect to /ws/events using a WebSocket client.","Send a small text frame and inspect the pong response.","Observe timestamps and connection lifecycle.","Disconnect and discuss backpressure and reconnection strategy."],"infrastructure":["Build and start the Compose stack.","Record baseline replica and response behavior.","Scale the API or worker in a local dev environment.","Observe health checks, replacement and recovery; record actual results."]};return m[id]||["Inspect the model.","Record observations.","State limitations."];}
function LabOutput({id,data}:{id:string;data:Lab}){
 if(id==="physical-clock")return <div className="lab-output"><div className="output-kpi"><span>Coordinator estimate</span><b>{data.coordinator_offset_ms??35} <small>ms</small></b><span className="subtext">Mean synthetic node offset</span></div><div className="output-table"><div className="output-table-head"><span>NODE</span><span>CURRENT OFFSET</span><span>ADJUSTMENT</span><span>AFTER CORRECTION</span></div>{(data.nodes||[]).map((n:any)=><div className="output-table-row" key={n.node}><b>{n.node}</b><span>{n.offset_ms>0?"+":""}{n.offset_ms} ms</span><span className={n.adjustment_ms>=0?"text-green":"text-orange"}>{n.adjustment_ms>0?"+":""}{n.adjustment_ms} ms</span><span className="corrected-value">{n.corrected_offset_ms} ms <CheckCircle2 size={13}/></span></div>)}</div><NumberedSteps items={data.steps||[]}/></div>;
 if(id==="lamport")return <div className="lab-output"><div className="trace-grid">{(data.events||[]).map((e:any)=><div className="trace-event" key={e.id}><div className="trace-event-top"><code>{e.id}</code><span className="trace-clock">L={e.clock}</span></div><b>{e.event}</b><span>{e.node}</span><small>{e.relation}</small></div>)}</div><div className="rule-box"><b>Lamport receive rule</b><code>L(receive) = max(L(local), L(message)) + 1</code><span>Scalar clocks can respect causality but cannot reliably distinguish concurrent events.</span></div><NumberedSteps items={data.rules||[]}/></div>;
 if(id==="snapshot")return <div className="lab-output"><div className="snapshot-processes">{(data.process_states||[]).map((p:any)=><div className="snapshot-node" key={p.node}><div className="snapshot-node-icon"><Cpu size={18}/></div><b>{p.node}</b><StatusPill status={p.state}/><span>{p.detail}</span></div>)}</div><SectionHead title="Channel state" meta="Messages in transit at snapshot time"/><div className="channel-list">{(data.channels||[]).map((c:any,i:number)=><div className="channel-row" key={i}><div className="channel-end">{c.from}</div><div className="channel-track"><span></span><ChevronRight size={15}/></div><div className="channel-end">{c.to}</div><StatusPill status={c.state}/>{c.messages?.length>0&&<div className="channel-message"><MessageSquare size={13}/>{c.messages.join(", ")}</div>}</div>)}</div></div>;
 if(id==="vector")return <div className="lab-output"><div className="vector-table"><div className="vector-head"><span>EVENT</span><span>PROCESS</span><span>VECTOR [P1, P2, P3]</span><span>MEANING</span></div>{(data.events||[]).map((e:any)=><div className="vector-row" key={e.id}><b>{e.id}</b><span>{e.node}</span><div className="vector-cells">{e.vector.map((v:number,i:number)=><span className={v?"vector-nonzero":""} key={i}>{v}</span>)}</div><span>{e.id==="A"?"Origin":e.id==="B"?"Same-process successor":e.id==="C"?"Cross-node receive":"Independent"}</span></div>)}</div><div className="comparison-cards">{(data.comparisons||[]).map((c:any,i:number)=><div key={i} className={cls("comparison-card",c.relation.includes("concurrent")&&"concurrent")}><span>{c.a} ↔ {c.b}</span><b>{c.relation}</b></div>)}</div></div>;
 if(id==="election")return <div className="lab-output"><div className="leader-winner"><div className="leader-winner-icon"><ShieldCheck size={23}/></div><div><span>ELECTED COORDINATOR</span><b>Node {data.leader??"—"}</b><small>Highest available node ID in the model</small></div><StatusPill status="leader"/></div><div className="node-grid">{(data.nodes||[]).map((n:any)=><div className={cls("election-node",n.state)} key={n.id}><div><Server size={17}/><b>Node {n.id}</b></div><StatusPill status={n.state}/><small>{n.state==="leader"?"Coordinator":n.state==="failed"?"No response":"Participating"}</small></div>)}</div><NumberedSteps items={data.election||[]}/></div>;
 if(id==="mutex")return <div className="lab-output"><div className="mutex-timeline">{(data.grant_order||[]).map((node:string,i:number)=><div className="mutex-step" key={node}><span className="mutex-num">{i+1}</span><div className="mutex-track"><b>{node}</b><span>{i===0?"REQUEST granted first":i===1?"Next in logical order":"Waits for earlier grants"}</span></div>{i<(data.grant_order||[]).length-1&&<ChevronRight size={16}/>}</div>)}</div><SectionHead title="Pending requests" meta="Ordered by timestamp → process ID"/><div className="request-list">{(data.requests||[]).map((r:any)=><div className="request-row" key={r.node}><span>{r.node}</span><code>timestamp={r.timestamp}</code><code>pid={r.process_id}</code><span className="request-priority">priority #{(data.grant_order||[]).indexOf(r.node)+1}</span></div>)}</div><NumberedSteps items={data.steps||[]}/></div>;
 if(id==="failure")return <div className="lab-output"><div className="failure-banner"><div><span>MISS THRESHOLD</span><b>{data.threshold??3} heartbeats</b></div><div className="failure-warning"><AlertCircle size={16}/> Suspicion is not a confirmed crash</div></div><div className="heartbeat-list">{(data.samples||[]).map((s:any,i:number)=><div className="heartbeat-row" key={i}><span className="heartbeat-time">{s.time}</span><div className={cls("heartbeat-node",s.heartbeat==="received"?"ok":"missed")}>{s.heartbeat==="received"?<CheckCircle2 size={15}/>:<AlertCircle size={15}/>}<b>{s.node}</b></div><div className="heartbeat-state">{s.heartbeat}</div><div className="miss-track">{Array.from({length:data.threshold||3},(_,j)=><i key={j} className={j<s.missed?"miss-fill":""}></i>)}</div><span className="miss-label">{s.missed} missed</span></div>)}</div><div className="failure-explain"><b>Interpretation</b><p>{data.interpretation||"A missed heartbeat may indicate a failure, network loss, or a slow process. Use the word ‘suspected’ until corroborating evidence is available."}</p></div></div>;
 if(id==="messaging")return <div className="lab-output"><div className="broker-status"><div className="broker-icon"><MessageSquare size={22}/></div><div><span>MESSAGE BROKER</span><b>RabbitMQ · durable queue</b><small>Queue: aegisgrid.events</small></div><StatusPill status={data.runtime_configured?"configured":"demo only"}/></div><div className="message-flow">{(data.flow||[]).map((step:string,i:number)=><div className="message-flow-step" key={step}><span>{String(i+1).padStart(2,"0")}</span><div><b>{step}</b><small>{["HTTP request / schema validation","PostgreSQL event_records","Durable queue publication","Independent worker consumer"][i]||"Communication step"}</small></div>{i<3&&<ChevronDown size={16}/>}</div>)}</div><div className="info-strip"><AlertCircle size={16}/><div><b>Delivery check</b><span>Inspect the event’s broker outcome and worker log / worker.processed row. Publication and processing are separate milestones.</span></div></div></div>;
 if(id==="stream")return <div className="lab-output"><div className="stream-lifecycle">{(data.lifecycle||[]).map((step:string,i:number)=><div key={step} className={cls("stream-stage",i===0?"stream-http":i===1?"stream-upgrade":i===4?"stream-close":"")}><span>{String(i+1).padStart(2,"0")}</span><b>{step}</b></div>)}</div><SectionHead title="Illustrative event frames" meta="Ordered sample messages"/><div className="frame-list">{(data.sample_events||[]).map((e:any)=><div className="frame-row" key={e.sequence}><span className="frame-sequence">#{e.sequence}</span><code>{e.type}</code><span className="frame-arrow">→</span><StatusPill status="received"/></div>)}</div><div className="code-note"><Code2 size={15}/> Live endpoint: <code>ws://localhost:8000/ws/events</code> — send text to receive a timestamped pong.</div></div>;
 return <div className="lab-output"><div className="infra-tip"><Terminal size={18}/><div><b>Docker Compose</b><p>Build and inspect the local stack. Scale a stateless worker separately to demonstrate concurrency.</p><pre>{(data.docker_commands||[]).join("\n")}</pre></div></div><div className="infra-tip"><Cloud size={18}/><div><b>Kubernetes</b><p>Inspect the actual workload state and test scaling/recovery in your development cluster.</p><pre>{(data.kubernetes_commands||[]).join("\n")}</pre></div></div><div className="info-strip"><ShieldCheck size={16}/><div><b>Runtime integrity</b><span>This panel is a runbook. It does not claim to observe a cluster unless the relevant runtime queries have completed.</span></div></div></div>;
}
function NumberedSteps({items}:{items:string[]}){return <div className="numbered-steps">{items.map((s,i)=><div key={i}><span>{String(i+1).padStart(2,"0")}</span><p>{s}</p></div>)}</div>}

function ArchitecturePage({services,apiState,onSelect}:{services:Overview["services"];apiState:string;onSelect:(s:string)=>void}){
 const nodes=[{name:"Frontend",subtitle:"React + TypeScript",icon:Globe2,x:"front",kind:"edge",desc:"Command centre UI"},{name:"API gateway",subtitle:"FastAPI · REST + WebSocket",icon:Server,x:"api",kind:"service",desc:"Validation, routing, concept labs"},{name:"PostgreSQL",subtitle:"Persistent application state",icon:Database,x:"db",kind:"data",desc:"Incidents and event ledger"},{name:"RabbitMQ",subtitle:"Durable event queue",icon:MessageSquare,x:"mq",kind:"data",desc:"Asynchronous service communication"},{name:"Event worker",subtitle:"Independent consumer process",icon:Cpu,x:"worker",kind:"service",desc:"Consumes and records processing acknowledgement"},{name:"Concept labs",subtitle:"Deterministic protocol models",icon:Workflow,x:"labs",kind:"lab",desc:"Clock, causality, election, snapshot, mutex"}];
 return <><PageIntro eyebrow="SYSTEM DESIGN / INTER-SERVICE CONTRACTS" title="Service topology" subtitle="A practical distributed application with synchronous request paths and asynchronous event processing." actions={<span className={cls("simulation-flag",apiState==="connected"?"":"muted-flag")}><span className={cls("status-dot",apiState==="connected"?"green":"amber")}></span>{apiState==="connected"?"API observed":"Runtime partly unverified"}</span>}/><div className="topology-summary"><div><b>06</b><span>Logical components</span></div><div><b>02</b><span>Communication patterns</span></div><div><b>01</b><span>Persistent event ledger</span></div><div><b>01</b><span>Independent queue consumer</span></div></div><section className="panel topology-panel"><SectionHead title="Logical service map" meta="Synchronous API flow + asynchronous broker flow"/><div className="topology-canvas"><div className="topology-row"><TopologyNode node={nodes[0]} state={apiState==="connected"?"up":"unverified"}/><div className="topology-link"><span>HTTPS / REST</span><i></i><ChevronRight size={15}/></div><TopologyNode node={nodes[1]} state={services.find(s=>s.name==="API gateway")?.state||"unverified"}/></div><div className="topology-branch"><div className="branch-line"></div><div className="branch-cols"><div className="topology-col"><div className="topology-link vertical-link"><span>SQL transactions</span><i></i><ChevronDown size={15}/></div><TopologyNode node={nodes[2]} state={apiState==="connected"?"up":"unverified"}/></div><div className="topology-col"><div className="topology-link vertical-link"><span>Durable publish</span><i></i><ChevronDown size={15}/></div><TopologyNode node={nodes[3]} state={services.find(s=>s.name==="RabbitMQ")?.state||"unverified"}/><div className="topology-link vertical-link"><span>AMQP / consume</span><i></i><ChevronDown size={15}/></div><TopologyNode node={nodes[4]} state="configured"/></div><div className="topology-col"><div className="topology-link vertical-link"><span>Internal handlers</span><i></i><ChevronDown size={15}/></div><TopologyNode node={nodes[5]} state="up"/></div></div></div><div className="topology-legend"><span><i className="legend-sync"></i> Synchronous</span><span><i className="legend-async"></i> Asynchronous</span><span><i className="legend-storage"></i> Persistent storage</span><span><i className="status-dot amber"></i> Unverified runtime</span></div></div></section><section className="panel service-contracts"><SectionHead title="Component contracts" meta="Boundaries, responsibilities, and failure domains"/><div className="contract-list">{nodes.map((n,i)=>{const actual=services.find(s=>s.name===n.name);return <button className="contract-row" key={n.name} onClick={()=>onSelect(n.name)}><div className={cls("contract-number",`contract-${n.kind}`)}>{String(i+1).padStart(2,"0")}</div><div className="contract-copy"><b>{n.name}</b><span>{n.subtitle}</span><p>{n.desc}</p></div><div className="contract-state"><span>{actual?.detail||"Configuration-defined component"}</span><StatusPill status={actual?.state||"configured"}/></div><ChevronRight size={16}/></button>})}</div></section><div className="info-strip"><Network size={17}/><div><b>Why this is distributed</b><span>The UI, API, database, broker, and consumer run as independent processes/containers. HTTP request/response demonstrates synchronous communication; RabbitMQ provides a separate asynchronous message path. Scaling only makes sense after defining ownership, consistency, and recovery behavior.</span></div></div></>;
}
function TopologyNode({node,state}:{node:any;state:string}){const Icon=node.icon;return <div className={cls("topology-node",`node-${node.kind}`)}><div className="topology-node-top"><div className="topology-node-icon"><Icon size={19}/></div><StatusPill status={state}/></div><b>{node.name}</b><span>{node.subtitle}</span><small>{node.desc}</small></div>}

function ScalePage({apiState,onNavigate}:{apiState:string;onNavigate:(s:string)=>void}){
 const [replicas,setReplicas]=useState(2);
 const [runbookStep,setRunbookStep]=useState(0);
 const [done,setDone]=useState<number[]>([]);
 const tasks=[{title:"Establish baseline",desc:"Record current replica counts, readiness, and API response behavior.",command:"docker compose ps"},{title:"Introduce controlled load",desc:"Use a repeatable request loop or load tool. Record throughput, latency, and error rate.",command:"for i in $(seq 1 100); do curl -s -o /dev/null -w '%{http_code} %{time_total}\n' http://localhost:8000/health/live; done"},{title:"Scale a stateless component",desc:"Compare one worker with multiple consumers. Do not scale a singleton stateful service without a design.",command:"docker compose up -d --scale worker=3"},{title:"Exercise recovery",desc:"Restart a test container or delete one Pod and observe readiness/replacement.",command:"kubectl delete pod <test-pod> -n aegisgrid"},{title:"Summarize evidence",desc:"Compare measurements and write down the bottleneck, the recovery time, and limits of the test.",command:"kubectl get pods -n aegisgrid -w"}];
 return <><PageIntro eyebrow="CAPACITY / EXPERIMENT DESIGN" title="Scale & resilience" subtitle="A reproducible experiment plan for horizontal scaling, workload recovery, and inter-service reliability." actions={<button className="btn-secondary" onClick={()=>onNavigate("runtime")}><Terminal size={15}/> Runtime diagnostics</button>}/><div className="connection-banner connection-demo"><div className="banner-icon"><Activity size={17}/></div><div><b>{apiState==="connected"?"Runtime API is responding":"Measurement values are planning examples"}</b><span>Simulated capacity curves below are illustrative. Replace them with measured runs before making performance claims.</span></div><span className="banner-mode">EXPERIMENT PLAN</span></div><div className="scale-grid"><section className="panel scale-model-panel"><SectionHead title="Replica planner" meta="Planning illustration — not live scaling"/><div className="replica-control"><label>Target replicas</label><div className="replica-stepper"><button onClick={()=>setReplicas(v=>Math.max(1,v-1))} disabled={replicas<=1}>−</button><b>{replicas}</b><button onClick={()=>setReplicas(v=>Math.min(8,v+1))} disabled={replicas>=8}>+</button></div></div><div className="replica-visual">{Array.from({length:8},(_,i)=><div key={i} className={cls("replica-box",i<replicas&&"replica-active")}><Server size={18}/><span>Pod {i+1}</span><small>{i<replicas?"Desired":"Not requested"}</small></div>)}</div><div className="replica-stats"><div><span>Desired</span><b>{replicas}</b></div><div><span>Max planner slots</span><b>8</b></div><div><span>Live observation</span><b>—</b></div></div><p className="subtle-note">This control changes only the planner illustration. It does not run kubectl or modify the cluster.</p></section><section className="panel scale-chart-panel"><SectionHead title="Illustrative load response" meta="Synthetic normalized capacity curve"/><div className="chart-legend"><span><i className="legend-blue"></i> Load handled</span><span><i className="legend-cyan"></i> Queue pressure</span></div><div className="scale-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={[1,2,3,4,5,6,7,8].map(n=>({replicas:n,throughput:Math.round(100*(1-Math.exp(-n/2.5))),queue:Math.max(8,80/n+10)}))} margin={{top:8,right:12,left:-20,bottom:4}}><CartesianGrid stroke="#202b3c" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="replicas" label={{value:"Replicas",position:"insideBottom",offset:-2,fill:"#7d8ca2",fontSize:10}} tick={{fill:"#77859a",fontSize:10}} axisLine={false} tickLine={false}/><YAxis tick={{fill:"#77859a",fontSize:10}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:"#101a29",border:"1px solid #29364a",borderRadius:8,color:"#e5edf8",fontSize:12}}/><Line type="monotone" dataKey="throughput" stroke="#6b8cff" strokeWidth={2} dot={{r:2}}/><Line type="monotone" dataKey="queue" stroke="#38b8cf" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div><div className="planning-note"><AlertCircle size={15}/><span>Real workloads may saturate at shared database, broker, CPU, or network limits. Throughput is not assumed to scale linearly.</span></div></section></div><section className="panel experiment-runbook"><SectionHead title="Experiment runbook" meta="Mark evidence as collected during your own run"/><div className="runbook-progress"><div><span>{done.length} of {tasks.length} steps marked complete</span><b>{Math.round(done.length/tasks.length*100)}%</b></div><div className="progress-track"><i style={{width:`${done.length/tasks.length*100}%`}}></i></div></div><div className="runbook-list">{tasks.map((t,i)=><div className={cls("runbook-item",done.includes(i)&&"completed")} key={t.title}><button className="runbook-check" onClick={()=>setDone(old=>old.includes(i)?old.filter(n=>n!==i):[...old,i])} aria-label={done.includes(i)?"Mark incomplete":"Mark complete"}>{done.includes(i)?<CheckCircle2 size={18}/>:<span>{String(i+1).padStart(2,"0")}</span>}</button><div className="runbook-copy"><b>{t.title}</b><p>{t.desc}</p><code>{t.command}</code></div><StatusPill status={done.includes(i)?"checked":"pending"}/></div>)}</div><div className="runbook-actions"><button className="btn-secondary" onClick={()=>{setDone([]);setRunbookStep(0);}}>Reset checklist</button><button className="btn-primary" onClick={()=>setRunbookStep(s=>s===0?1:0)}><Play size={14}/>{runbookStep?"Hide measurement notes":"Show measurement template"}</button></div>{runbookStep===1&&<div className="measurement-template"><h4>Capture actual evidence</h4><p>For each run, document commit/image tag, number of replicas, request concurrency, duration, p50/p95 latency, throughput, HTTP error rate, worker backlog, recovery time, and test environment. Do not fill this with the synthetic graph values.</p></div>}</section></>;
}

function RuntimePage({services,apiState,selectedService,onSelect,onRefresh}:{services:Overview["services"];apiState:string;selectedService:string;onSelect:(s:string)=>void;onRefresh:()=>void}){
 const snippets:Record<string,string[]>={"API gateway":["curl -fsS http://localhost:8000/health/live","curl -fsS http://localhost:8000/health/ready","curl -fsS http://localhost:8000/api/overview"],"PostgreSQL":["docker compose exec postgres pg_isready -U aegisgrid -d aegisgrid","docker compose logs --tail=80 postgres"],"RabbitMQ":["docker compose exec rabbitmq rabbitmq-diagnostics -q ping","Open http://localhost:15672 (local dev broker UI)","docker compose logs --tail=80 rabbitmq"],"Event worker":["docker compose logs --tail=100 worker","docker compose up -d --scale worker=3","curl -fsS http://localhost:8000/api/events"],"Frontend":["Open http://localhost:3000","docker compose logs --tail=80 frontend"],"Concept labs":["curl -fsS http://localhost:8000/api/concepts","curl -fsS http://localhost:8000/api/labs/lamport"]};
 const k8s=["kubectl get deploy,pods,svc -n aegisgrid","kubectl rollout status deployment/aegisgrid-api -n aegisgrid","kubectl logs deployment/aegisgrid-worker -n aegisgrid --tail=100","kubectl top pods -n aegisgrid  # requires Metrics Server"];
 const selected=snippets[selectedService]||snippets["API gateway"];
 return <><PageIntro eyebrow="OPERATIONS / OBSERVABILITY" title="Runtime diagnostics" subtitle="Copy and run targeted checks against your local Docker or Kubernetes environment." actions={<button className="btn-secondary" onClick={onRefresh}><RefreshCw size={15}/> Re-check API</button>}/><div className={cls("connection-banner",apiState==="connected"?"connection-live":"connection-demo")}><div className="banner-icon">{apiState==="connected"?<CheckCircle2 size={17}/>:<AlertCircle size={17}/>}</div><div><b>{apiState==="connected"?"API checks succeeded":"Container runtime is not directly queried by this dashboard"}</b><span>{apiState==="connected"?"The dashboard can reach the API and readiness dependency. Use Docker/Kubernetes commands below to inspect actual orchestrator state.":"Start Docker Compose and refresh. Runtime commands below are suggestions to execute in your terminal; their results are not fabricated here."}</span></div></div><div className="runtime-grid"><section className="panel runtime-services"><SectionHead title="Components" meta="Choose a service to inspect"/>{[{name:"Frontend",detail:"React single-page app",icon:Globe2},{name:"API gateway",detail:"REST, WebSocket, lab endpoints",icon:Server},{name:"PostgreSQL",detail:"Incident and event persistence",icon:Database},{name:"RabbitMQ",detail:"Durable message queue",icon:MessageSquare},{name:"Event worker",detail:"Independent message consumer",icon:Cpu},{name:"Concept labs",detail:"Protocol simulations",icon:Workflow}].map(s=>{const Icon=s.icon;const actual=services.find(x=>x.name===s.name);return <button className={cls("runtime-service",selectedService===s.name&&"selected")} key={s.name} onClick={()=>onSelect(s.name)}><Icon size={17}/><span><b>{s.name}</b><small>{actual?.detail||s.detail}</small></span><StatusPill status={actual?.state||(s.name==="Concept labs"?"up":"unverified")}/></button>})}</section><section className="panel runtime-checks"><SectionHead title={selectedService} meta="Local inspection commands"/><p className="runtime-description">Run the commands in your own terminal from the project root. Output and exit codes are authoritative; this UI does not execute host commands.</p><div className="command-block-head"><Terminal size={14}/> DOCKER COMPOSE <button onClick={()=>navigator.clipboard?.writeText((selected||[]).join("\n"))}>Copy commands</button></div><pre className="command-block">{selected.map((c,i)=>`# ${i+1}\n${c}`).join("\n\n")}</pre><div className="command-block-head"><Cloud size={14}/> KUBERNETES <button onClick={()=>navigator.clipboard?.writeText(k8s.join("\n"))}>Copy commands</button></div><pre className="command-block">{k8s.join("\n")}</pre><div className="runtime-caution"><Shield size={16}/><span>Only run these against your intended development Compose project or namespace. Never expose Docker socket or cluster credentials to the browser.</span></div></section></div><section className="panel diagnostics-checklist"><SectionHead title="Readiness semantics" meta="Healthy process ≠ healthy application"/><div className="diagnostic-grid"><div><CheckCircle2 size={17}/><b>Liveness</b><p>Can the process respond? Used to decide whether a container should be restarted.</p><code>/health/live</code></div><div><Database size={17}/><b>Readiness</b><p>Can this instance safely accept traffic? API readiness checks database reachability.</p><code>/health/ready</code></div><div><Radio size={17}/><b>Worker health</b><p>Consumer availability is verified with broker diagnostics and worker logs/ledger events.</p><code>docker compose logs worker</code></div></div></section></>;
}

